class Carousel{constructor(selector,options={}){this.root=typeof selector==="string"?document.querySelector(selector):selector;if(!this.root)return;this.slides=Array.from(this.root.querySelectorAll(".carousel-slide"));this.interval=options.interval||3e3;this.current=0;this.timer=null;this.paused=false;this.touchStartX=0;this.touchEndX=0;this._buildDots();this._bindControls();this._bindTouch();this._bindHover();this._goTo(0);this._startTimer()}_buildDots(){const dotsContainer=this.root.querySelector(".carousel-dots");if(!dotsContainer)return;dotsContainer.innerHTML="";this.dots=this.slides.map((_,i)=>{const dot=document.createElement("button");dot.className="carousel-dot w-2 h-2 rounded-full transition-all duration-300 focus:outline-none";dot.setAttribute("aria-label",`Go to slide ${i+1}`);dot.addEventListener("click",()=>{this._goTo(i);this._resetTimer()});dotsContainer.appendChild(dot);return dot})}_bindControls(){const prev=this.root.querySelector(".carousel-prev");const next=this.root.querySelector(".carousel-next");if(prev)prev.addEventListener("click",()=>{this._prev();this._resetTimer()});if(next)next.addEventListener("click",()=>{this._next();this._resetTimer()})}_bindTouch(){this.root.addEventListener("touchstart",e=>{this.touchStartX=e.changedTouches[0].screenX;this.paused=true},{passive:true});this.root.addEventListener("touchend",e=>{this.touchEndX=e.changedTouches[0].screenX;const delta=this.touchStartX-this.touchEndX;if(Math.abs(delta)>50){delta>0?this._next():this._prev();this._resetTimer()}setTimeout(()=>{this.paused=false},500)},{passive:true})}_bindHover(){this.root.addEventListener("mouseenter",()=>{this.paused=true});this.root.addEventListener("mouseleave",()=>{setTimeout(()=>{this.paused=false},200)})}_goTo(index){this.slides.forEach((slide,i)=>{slide.classList.toggle("active",i===index);slide.classList.toggle("inactive",i!==index)});if(this.dots){this.dots.forEach((dot,i)=>{dot.classList.toggle("bg-brand-500",i===index);dot.classList.toggle("dark:bg-brand-400",i===index);dot.classList.toggle("bg-slate-300",i!==index);dot.classList.toggle("dark:bg-slate-600",i!==index);dot.classList.toggle("w-4",i===index);dot.classList.toggle("w-2",i!==index)})}this.current=index}_next(){this._goTo((this.current+1)%this.slides.length)}_prev(){this._goTo((this.current-1+this.slides.length)%this.slides.length)}_startTimer(){this.timer=setInterval(()=>{if(!this.paused)this._next()},this.interval)}_resetTimer(){clearInterval(this.timer);this._startTimer()}destroy(){clearInterval(this.timer)}}